namespace ghidra.app.plugin.assembler.sleigh.expr.match;




using ghidra.app.plugin.processors.sleigh.expression;

/**
 * Base implementation for expression matchers
 *
 * @param <T> the type of expression matched
 */
public abstract class AbstractExpressionMatcher<T> : ExpressionMatcher<T> where T : PatternExpression {
	protected Set<Class<T>> ops;

	public AbstractExpressionMatcher(Set<Class<T>> ops) {
		this.ops = Set.copyOf(ops);
	}

	public AbstractExpressionMatcher(Class<T> cls) {
		this.ops = Set.of(cls);
	}

	protected T opMatches(PatternExpression expression) {
		return ops.stream()
				.filter(op => op.isInstance(expression))
				.map(op => op.cast(expression))
				.findAny()
				.orElse(null);
	}

	protected abstract bool matchDetails(T expression,
			Map<ExpressionMatcher<object>, PatternExpression> result);

	/* @Override */
	public bool match(PatternExpression expression,
			Map<ExpressionMatcher<object>, PatternExpression> result) {
		T t = opMatches(expression);
		if (t == null) {
			return false;
		}
		if (!matchDetails(t, result)) {
			return false;
		}
		return recordResult(t, result);
	}

	protected bool recordResult(PatternExpression expression,
			Map<ExpressionMatcher<object>, PatternExpression> result) {
		PatternExpression already = result.put(this, expression);
		if (already == null) {
			return true;
		}
		return expressionsIdenticallyDefined(already, expression);
	}

	protected static bool expressionsIdenticallyDefined(PatternExpression a,
			PatternExpression b) {
		if (a.GetType() != b.GetType()) {
			return false;
		}
		if (a is EndInstructionValue) {
			return true;
